s = input()
t = input()
a = list(map(int, input().split()))

def ok(n):
	bad = set()
	for i in range(n):
		bad.add(a[i] - 1)
	pt = 0
	ps = 0
	while pt < len(t) and ps < len(s):
		if ps in bad:
			ps += 1
		elif t[pt] == s[ps]:
			ps += 1
			pt += 1
		else:
			ps += 1
	return pt == len(t)
low = 0
high = len(s)
while high >= low:
	mid = (high + low) // 2
	if ok(mid):
		poss = mid
		low = mid + 1
	else:
		high = mid - 1
print(poss)
